sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    // Check if the attachment field is populated
    if (current.uploadfile.nil()) {
        gs.info('No attachment uploaded. Skipping processing for record: ' + current.sys_id);
        return;
    }

    // Fetch the latest attachment for the record
    var attachmentGR = new GlideRecord('sys_attachment');
    attachmentGR.addQuery('sys_id', current.uploadfile);
    attachmentGR.query();

    if (attachmentGR.next()) {
        var attachmentSysId = attachmentGR.sys_id;

        try {
            // Retrieve attachment content
            var attachment = new GlideSysAttachment();
            var contentStream = attachment.getContentStream(attachmentSysId);
            var parser = new sn_impex.GlideExcelParser();
            parser.setSource(contentStream);

            var sheetNames = parser.getSheetNames();
            var processedSheets = 0; // Counter for successful sheets

            // Iterate over each worksheet in the Excel workbook
            for (var i = 0; i < sheetNames.length; i++) {
                parser.setSheetName(sheetNames[i]);

                if (parser.parse()) {
                    var headers = parser.getColumnHeaders();
                    if (headers.length < 4) {
                        gs.addErrorMessage('Invalid number of headers in the sheet: ' + sheetNames[i]);
                        continue;
                    }

                    var content = buildCsvAndPdf(headers, parser);
                    var newCsv = content.csv;
                    var newPdf = content.pdf;

                    // Attach processed CSV
                    var grAttachment = new GlideSysAttachment();
                    grAttachment.write(current, 'Processed_File.csv', 'text/csv', newCsv);
                    gs.info("CSV file successfully attached to record: " + current.sys_id);

                    // Attach processed PDF
                    var pdfAPI = new sn_pdfgeneratorutils.PDFGenerationAPI();
                    var result = pdfAPI.convertToPDF(newPdf, current.getTableName(), current.getValue('sys_id'), current.getValue('number') + '_PDFfile');
                    gs.info("PDF file successfully attached to record: " + current.sys_id);

                    processedSheets++; // Increment counter for successful processing
                } else {
                    gs.addErrorMessage('Error parsing sheet: ' + sheetNames[i] + ' - ' + parser.getErrorMessage());
                }
            }

            if (processedSheets > 0) {
                // Success message after all sheets are processed
                gs.addInfoMessage('Attachment processed successfully. All valid sheets have been updated.');
            } else {
                gs.addErrorMessage('No valid sheets were processed.');
            }
        } catch (error) {
            gs.addErrorMessage('Error processing attachment: ' + error.message);
        }
    } else {
        gs.addErrorMessage('No attachment found for record: ' + current.sys_id);
    }

    /**
     * Build CSV and PDF content from headers and parser rows.
     */
    function buildCsvAndPdf(headers, parser) {
        // Initialize CSV content
        var csvContent = headers.join(',') + ',Status\r\n';
        var pdfContent = '<html><body>';
        pdfContent += '<h2>Processed Data</h2>';
        pdfContent += '<ul>'; // Start the list for PDF content

        while (parser.next()) {
            var row = parser.getRow();
            var updateStatus = updateCase(row, headers);

            // Add row to CSV
            csvContent += headers.map(header => (row[header] || '')).join(',') + ',' + updateStatus + '\r\n';

            // Add row to PDF as a list item
            pdfContent += '<li>';
            headers.forEach(function(header) {
                pdfContent += '<p><strong>' + header + ':</strong> ' + (row[header] || 'N/A') + '</p>\n';
            });
            pdfContent += '<p><strong>Status:</strong> ' + updateStatus + '</p>';
            pdfContent += '</li>';
        }

        pdfContent += '</ul></body></html>'; // End the list and the HTML

        return {
            csv: csvContent,
            pdf: pdfContent
        };
    }

    /**
     * Update a case using the row data.
     */
    function updateCase(row, headers) {
        var inputs = {
            req_excel_record: current.getDisplayValue('sys_id'),
            policy_number: row[headers[0]],
            member_dependent_number: row[headers[1]],
            loan_number: row[headers[2]],
            le_id: row[headers[3]]
        };

        try {
            var result = sn_fd.FlowAPI.getRunner()
                .subflow('x_rptp_kotak.kotak__assigning_cases_to_users')
                .inForeground()
                .withInputs(inputs)
                .run();

            var outputs = result.getOutputs();
            return outputs.uploadstat || 'Failed';
        } catch (error) {
            gs.error('Error updating case for row: ' + JSON.stringify(row) + ' - ' + error.message);
            return 'Error';
        }
    }

    try {
        gs.eventQueue("x_rptp_kotak.job_id_email", current);
    } catch (e) {
        gs.info(e);
    }

})(current, previous);
